package glitch

import data.glitch_lib

weak_algorithms = {"DES", "3DES", "RC2", "RC4", "MD5", "SHA1", "SHA-1", "ECB"}
weak_tls_versions = {"TLSv1.0", "TLSv1.1", "SSLv3", "TLS1.0", "TLS1.1"}
encryption_keywords = {"encryption", "encrypted", "encrypt", "kms_key_id", "sse_algorithm", "cipher", "ciphers", "tls_version", "ssl_policy", "min_tls_version", "ssl_mode", "hash_algorithm", "digest", "key_exchange"}

disabled_flags = {"encryption_enabled", "encrypted", "sse_enabled", "tls_enabled", "ssl_enabled", "encryption"}
inssl_flags = {"tls_disabled", "ssl_disabled", "insecure_ssl", "skip_ssl", "verify_ssl", "http_protocol"}

is_weak_algorithm(value) {
    value.ir_type == "String"
    alg :=weak_algorithms[_]
    contains(lower(value.value), lower(alg))
}

is_weak_tls_version(value) {
    value.ir_type == "String"
    ver :=weak_tls_versions[_]
    contains(value.value, ver)
}

is_encryption_disabled(attr) {
    attr.name == disabled_flags[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == false
}

is_insecure_ssl(attr) {
    attr.name == inssl_flags[_]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

encryption_related(name) {
    kw := encryption_keywords[_]
    contains(lower(name), kw)
}

collect_hash_values(hash_obj) = values {
    hash_obj.ir_type == "Hash"
    values = {v | some k; v := hash_obj.value[k]}
}

collect_array_values(arr_obj) = values {
    arr_obj.ir_type == "Array"
    values = {v | v := arr_obj.value[_]}
}

deep_contains_weak(value) {
    is_weak_algorithm(value)
} else {
    value.ir_type == "Hash"
    vals := collect_hash_values(value)
    val := vals[_]
    deep_contains_weak(val)
} else {
    value.ir_type == "Array"
    vals := collect_array_values(value)
    val := vals[_]
    deep_contains_weak(val)
}

deep_contains_weak_tls(value) {
    is_weak_tls_version(value)
} else {
    value.ir_type == "Hash"
    vals := collect_hash_values(value)
    val := vals[_]
    deep_contains_weak_tls(val)
} else {
    value.ir_type == "Array"
    vals := collect_array_values(value)
    val := vals[_]
    deep_contains_weak_tls(val)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    encryption_related(attr.name)
    is_weak_algorithm(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of broken or risky cryptographic algorithm - Avoid using weak or deprecated cryptographic algorithms. (CWE-327)"
    }
}

